skeleton:
variable "environment" {
  # type, description, et un bloc validation à compléter
}

solution:
variable "environment" {
  description = "Environnement cible (dev, staging ou prod)"
  type        = string

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment doit être dev, staging ou prod."
  }
}
